      if (kind === 'xln') { const n = r.int(1, 6), e1 = r.int(1, 3), f = (x) => x ** n * Math.log(x), val0 = ((Math.exp(e1 * (n + 1)) * 0 + 0)); const up = r.pick([2, 3, 4, 5, 6, 7, 8, 9]); const I = (up ** (n + 1) / (n + 1)) * Math.log(up) - (up ** (n + 1) - 1) / (n + 1) ** 2; return { q: `Calculer à l’aide d’une intégration par parties ${M(`\\displaystyle\\int_{1}^{${up}}${px(n)}\\ln x\\,\\mathrm{d}x`)}.`, a: `On pose ${M('u(x)=\\ln x')}, ${M(`v'(x)=${px(n)}`)} : ${M("u'(x)=\\dfrac{1}{x}")}, ${M(`v(x)=\\dfrac{x^{${n + 1}}}{${n + 1}}`)}. ${M(`\\int_{1}^{${up}}uv'=\\left[\\dfrac{x^{${n + 1}}}{${n + 1}}\\ln x\\right]_{1}^{${up}}-\\int_{1}^{${up}}\\dfrac{${px(n)}}{${n + 1}}\\,\\mathrm{d}x=\\dfrac{${up ** (n + 1)}}{${n + 1}}\\ln ${up}-\\dfrac{${up ** (n + 1)}-1}{${(n + 1) ** 2}}`)}.`, ok: () => Math.abs(simpson(f, 1, up) - I) < 1e-6 * Math.max(1, Math.abs(I)) && val0 === 0 }; }
      const a = r.int(1, 12), f = (x) => x * x * Math.exp(-a * x), I = (u) => -Math.exp(-a * u) * (u * u / a + (2 * u) / (a * a) + 2 / (a ** 3)), up = r.int(1, 5), v0 = I(up) - I(0);
